sys_ui_action.script:
// Run the same calculation the business rule uses, for the record currently on screen
var result = new BudgetSpreadsheetTotal().recalculate(current.getUniqueValue());

if (!result) {
    // Defensive branch - recalculate() only returns null if called without a sys_id
    gs.addErrorMessage('Could not identify the record to recalculate.');
} else if (result.candidates > 0 && result.files === 0) {
    // Files are attached but none could be read, so the old total is still showing
    gs.addErrorMessage('A spreadsheet is attached but could not be read. ' +
                       'The total has been left unchanged - check the system log for details.');
} else if (result.reset) {
    // No spreadsheet on the record, so the total was cleared back to zero
    gs.addInfoMessage('No spreadsheet is attached. Total reset to 0.00.');
} else {
    // Normal success path - show the figures so the user can sanity check them
    gs.addInfoMessage('Total updated to ' + result.total.toFixed(2) +
                      ' from ' + result.rows + ' line item(s) across ' + result.files + ' file(s).');
}

// Reload the form so the refreshed total amount value is visible
action.setRedirectURL(current);
